    "// ting zhi — stopped",
    "// qu xiao — cancelled",
    "// bu chi — does not eat",
    "// cheng le — has become",
    "/** Search terms for finding older memories on this topic. */",
    "// zhu — live/reside",
    "// ju zhu — reside",
    "// ban — move",
    "// dizhi — address",
    "// chengshi — city",
    "// shenghuo zai — live in",
    "// bu zai zhu — no longer live",
    "// che — car",
    "// kai che — drive",
    "// jia shi — drive",
    "// diandong che — EV",
    "// zixingche — bicycle",
    "// motuo — motorbike",
    "// mai che — sold the car",
    "// huan che — changed the car",
    "// bu zai kai — no longer drives",
    "// bao fei — written off",
    "// gongzuo — work",
    "// gongsi — company",
    "// zhiwei — position",
    "// zhiye — profession",
    "// shangban — go to work",
    "// guzhu — employer",
    "// jiuye — employed",
    "// huan gongzuo — changed job",
    "// ru zhi — joined",
    "// sushi — vegetarian",
    "// chi su — eat vegetarian",
